    if (fs::exists(m_root / "attachments")) {
        for (const auto& entry : fs::recursive_directory_iterator(m_root / "attachments"))
            if (entry.is_regular_file() &&
                !kept_attachments.count(fs::relative(entry.path(), m_root).generic_u8string()))
