ProviderRequest AnthropicCodec::build(const TurnTranscript& transcript, const ProviderProfile& profile, RequestKind kind) const
{
    const bool title = kind == RequestKind::ConversationTitle;
    json       messages = json::array();
    std::vector<Message> built = normalized(conversation(transcript));
    for (const Message& message : built)
        messages.push_back(message_json(message));
    // A breakpoint on the newest user content caches the turn so far for the
    // next request of the same turn.
    for (auto it = messages.rbegin(); it != messages.rend(); ++it)
        if ((*it)["role"] == "user") {
            (*it)["content"].back()["cache_control"] = ephemeral();
            break;
        }

    ProviderRequest request;
    if (clears_skills(profile))
        request.headers.push_back({"anthropic-beta", kClearAtBeta});
    request.body = json{{"model", profile.model},
                        {"max_tokens", profile.max_tokens},
                        {"stream", true},
                        {"system", json::array({json{{"type", "text"},
                                                     {"text", title ? std::string(kConversationTitleInstructions) : transcript.instructions},
                                                     {"cache_control", ephemeral()}}})},
                        {"messages", std::move(messages)}};
    if (!title && !transcript.tools.empty())
        request.body["tools"] = tools_json(transcript.tools);
    // The model list offers levels only for models with adaptive thinking,
    // where the level is effort and thinking stays adaptive.
    if (!title && !profile.effort.empty()) {
        request.body["thinking"]      = json{{"type", "adaptive"}};
        request.body["output_config"] = json{{"effort", profile.effort}};
    }
    // An empty system text is not accepted; the loop never builds one for a
    // reply (the page supplies the instructions), but a test may.
    if (request.body["system"][0]["text"] == "")
        request.body.erase("system");
    return request;
}

#pragma once

// What a provider agent keeps of a turn in the chat's record, for the test
// agents that stand in for one: the person's side as it was sent, the app's
// notes after it (the turn's own last), and the replies, so a later request carries them the way
// the real loop's record does. Pictures and skills are left to the tests that
// run the real loop.

#include "slic3r/GUI/JusPrin/Agent/AgentService.hpp"

#include <nlohmann/json.hpp>

#include <string>
#include <vector>

namespace JusPrinTest {

inline Slic3r::GUI::JusPrin::Agent::RecordPart kept_text(const std::string& words)
{
    return {Slic3r::GUI::JusPrin::Agent::RecordPart::Kind::Text, words};
}

inline std::vector<Slic3r::GUI::JusPrin::Agent::RecordItem> kept_person_side(const Slic3r::GUI::JusPrin::Agent::AgentRequest& request)
{
    using namespace Slic3r::GUI::JusPrin::Agent;
    std::vector<RecordItem> items;
    // The words, then any print issue's context as a part of its own.
    const auto person = [](const std::string& id, const std::string& words, const std::string& issue_context) {
        RecordItem item{RecordItem::Kind::User, id, {kept_text(words)}};
        if (!issue_context.empty())
            item.parts.push_back(kept_text(issue_context));
        return item;
    };
    for (const AgentUnsentMessage& message : request.unsent)
        if (!message.note)
            items.push_back(person(message.id, message.text, message.issue_context));
    if (!request.source.empty() && request.note.empty())
        items.push_back(person(request.source, request.user_text, request.issue_context));
    for (const AgentUnsentMessage& message : request.unsent)
        if (message.note)
            items.push_back({RecordItem::Kind::Operator, message.id, {}, message.text});
    if (!request.note.empty())
        items.push_back({RecordItem::Kind::Operator, request.source, {}, request.note});
    return items;
}

// A reply as a Responses message item.
inline Slic3r::GUI::JusPrin::Agent::RecordItem kept_reply(const std::string& words)
{
    return {Slic3r::GUI::JusPrin::Agent::RecordItem::Kind::Assistant, {}, {}, {},
            nlohmann::json{{"type", "message"}, {"role", "assistant"}, {"content", words}}};
}

// A call as a Responses function_call item.
inline Slic3r::GUI::JusPrin::Agent::RecordItem kept_call(const std::string& call_id, const std::string& tool,
                                                         const std::string& arguments_json)
{
    return {Slic3r::GUI::JusPrin::Agent::RecordItem::Kind::Assistant, {}, {}, {},
            nlohmann::json{{"type", "function_call"}, {"call_id", call_id}, {"name", tool}, {"arguments", arguments_json}}};
}

inline Slic3r::GUI::JusPrin::Agent::RecordItem kept_result(const Slic3r::GUI::JusPrin::Agent::AgentToolResult& result)
{
    Slic3r::GUI::JusPrin::Agent::RecordItem item{Slic3r::GUI::JusPrin::Agent::RecordItem::Kind::Results};
    item.results.push_back({result.call_id, result.output_json, result.state != "succeeded"});
    return item;
}

inline void keep(const Slic3r::GUI::JusPrin::Agent::AgentRequest& request,
                 std::vector<Slic3r::GUI::JusPrin::Agent::RecordItem> items)
{
    if (request.on_recorded && !items.empty())
        request.on_recorded("responses", std::move(items));
}

} // namespace JusPrinTest

